+    }
+    assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", headers })).status, 403);
+  }
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: { authorization: "Bearer viewer-key" }, body: { portions: 1 } })).status, 403);
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("cooks can perform kitchen tasks and managers can read saved audit entries", async () => {
+  const { handle, store } = app();
+  let saves = 0;
+  store.save = () => { saves++; };
+  const headers = { authorization: "Bearer cook-key" };
+  const take = await handle({ method: "POST", path: "/stocktakes", body: { location: "fridge" } });
+  assert.equal(take.status, 201);
+  const requests = [
+    { path: "/recipes/1/cook", body: { portions: 1 } },
+    { path: "/batches/1/waste", body: { qty: 0.1 } },
+    { path: "/temperatures", body: { location: "fridge", celsius: 4 } },
+    { path: `/stocktakes/${take.body.id}/counts`, body: { batchId: 3, counted: 1 } },
+  ];
+  for (const request of requests) {
+    const response = await handle({ ...request, method: "POST", headers });
+    assert.ok(response.status < 300, JSON.stringify(response));
+  }
+  assert.equal(saves, 5);
+  const audit = await handle({ path: "/audit" });
+  assert.equal(audit.status, 200);
+  assert.equal(audit.body.length, 5);
+  assert.deepEqual(audit.body[0], {
+    time: "2026-10-28T10:00:00.000Z", name: "Seed cook", method: "POST",
+    path: requests[3].path, status: 200,
+  });
+  assert.equal(audit.body.at(-1).name, "Seed manager");
+  assert.equal(JSON.stringify(audit.body).includes("cook-key"), false);
+  assert.equal(saves, 5);
+});
